const dashboardScript = `
(() => {
  const shell = document.querySelector('.shell');
  const sidebar = document.querySelector('.sidebar');
  const navToggle = document.querySelector('[data-nav-toggle]');
  const setNavOpen = (open) => {
    sidebar?.classList.toggle('nav-open', open);
    shell?.classList.toggle('nav-open', open);
    navToggle?.setAttribute('aria-expanded', open ? 'true' : 'false');
  };
  navToggle?.addEventListener('click', () => setNavOpen(!sidebar?.classList.contains('nav-open')));
  document.querySelectorAll('.nav a').forEach((link) => link.addEventListener('click', () => setNavOpen(false)));
  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') setNavOpen(false);
  });
  const dialog = document.getElementById('confirm-dialog');
  const title = document.getElementById('confirm-title');
  const copy = document.getElementById('confirm-copy');
  const confirmButton = document.getElementById('confirm-submit');
  let pendingForm = null;
  document.addEventListener('click', (event) => {
    const button = event.target.closest('[data-confirm]');
    if (!button || !dialog) return;
    event.preventDefault();
    pendingForm = button.closest('form');
    title.textContent = button.dataset.confirmTitle || 'Are you sure?';
    copy.textContent = button.dataset.confirmMessage || 'This action cannot be undone.';
    confirmButton.textContent = button.dataset.confirmLabel || 'Continue';
    confirmButton.className = 'btn ' + (button.dataset.confirmTone === 'danger' ? 'danger' : 'primary');
    dialog.showModal();
  });
  confirmButton?.addEventListener('click', () => {
    if (!pendingForm) return dialog?.close();
    const form = pendingForm;
    pendingForm = null;
    dialog?.close();
    form.requestSubmit();
  });
  document.querySelectorAll('[data-copy-target]').forEach((button) => {
    button.addEventListener('click', async () => {
      const target = document.querySelector(button.getAttribute('data-copy-target'));
      if (!target) return;
      try {
        await navigator.clipboard.writeText(target.textContent || '');
        const previous = button.textContent;
        button.textContent = 'Copied';
        setTimeout(() => button.textContent = previous, 1400);
      } catch {}
    });
  });
})();
`

const landingScript = `
(() => {
  document.querySelectorAll('[data-copy-value]').forEach((button) => {
    button.addEventListener('click', async () => {
      try {
        await navigator.clipboard.writeText(button.dataset.copyValue || '');
        const previous = button.innerHTML;
        button.textContent = 'Copied';
        setTimeout(() => button.innerHTML = previous, 1400);
      } catch {}
    });
  });
})();
`

func Icon(name string) string { return UIIcons[name] }

func FormatTime(value int64) string {
	if value <= 0 {
		return "—"
	}
	return time.UnixMilli(value).Format("Jan 2, 2006, 3:04 PM")
}

func navLink(href, key, label string, active bool) string {
	className := ""
	if active {
		className = ` class="active"`
	}
	return `<a href="` + href + `" aria-label="` + Escape(label) + `" title="` + Escape(label) + `"` + className + `><span class="nav-icon">` + UIIcons[key] + `</span><span>` + Escape(label) + `</span></a>`
}

func DashboardPage(options DashboardOptions) string {
	initial := "U"
	if strings.TrimSpace(options.Email) != "" {
		initial = strings.ToUpper(string([]rune(options.Email)[0]))
	}
	brand := `<div class="brand"><img class="logo" src="/assets/codelocal-icon.png" alt=""><span class="brand-name">CodeLocal</span><span class="brand-tag">CLOUD</span><button class="mobile-nav-toggle" type="button" aria-label="Open navigation" aria-expanded="false" data-nav-toggle><span class="control-icon">` + UIIcons["menu"] + `</span></button></div>`
	var nav strings.Builder
	nav.WriteString(`<div class="nav-label">Control plane</div><nav class="nav">`)
	nav.WriteString(navLink("/dashboard", "overview", "Overview", options.Active == "overview"))
	nav.WriteString(navLink("/dashboard/workspaces", "workspaces", "Workspaces", options.Active == "workspaces"))
	nav.WriteString(navLink("/dashboard/devices", "devices", "Devices", options.Active == "devices"))
	nav.WriteString(navLink("/dashboard/connect", "connect", "Connect ChatGPT", options.Active == "connect"))
	nav.WriteString(`</nav><div class="nav-label">Community</div><nav class="nav">`)
	nav.WriteString(navLink("/dashboard/invite", "invite", "Invite", options.Active == "invite"))
	nav.WriteString(navLink("/dashboard/leaderboard", "leaderboard", "Leaderboard", options.Active == "leaderboard"))
	if options.IsAdmin {
		nav.WriteString(`</nav><div class="nav-label">Administration</div><nav class="nav">`)
		nav.WriteString(navLink("/dashboard/admin", "admin", "Admin", options.Active == "admin"))
	}
	nav.WriteString(`</nav>`)
	logout := `<form method="post" action="/logout">` + Hidden(map[string]string{"csrf": options.CSRF}) + `<button class="btn ghost small" type="submit" aria-label="Sign out" title="Sign out"><span class="signout-icon" aria-hidden="true">` + UIIcons["logout"] + `</span><span class="signout-label">Sign out</span></button></form>`
	status := `<div class="sidebar-spacer"></div><div class="sidebar-status"><div class="sidebar-status-title"><span class="status-dot green"></span>Cloud connected</div><div class="sidebar-status-copy">Local source code and secrets stay on your machine.</div></div><div class="sidebar-foot"><div class="avatar">` + Escape(initial) + `</div><div class="account"><div class="account-email">` + Escape(options.Email) + `</div><div class="account-meta">CodeLocal account</div></div>` + logout + `</div>`
	subtitle := ""
	if strings.TrimSpace(options.Subtitle) != "" {
		subtitle = `<div class="sub">` + Escape(options.Subtitle) + `</div>`
	}
	actions := ""
	if strings.TrimSpace(options.Actions) != "" {
		actions = `<div class="top-actions">` + options.Actions + `</div>`
	}
	return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="color-scheme" content="light dark">` + brandHead + `<title>` + Escape(options.Title) + ` · CodeLocal</title><style>` + styles + mainPortExtras + iosDashboardTheme + `</style></head><body class="dashboard-body page-` + Escape(options.Active) + `"><div class="shell"><div class="sidebar-column"><aside class="sidebar">` + brand + nav.String() + status + `</aside></div><main class="main"><header class="top"><div class="top-copy"><div class="eyebrow"><span class="status-dot green"></span>CodeLocal Cloud</div><div class="h1">` + Escape(options.Title) + `</div>` + subtitle + `</div>` + actions + `</header>` + options.Body + `</main></div><dialog id="confirm-dialog"><div class="modal"><div class="modal-icon">` + UIIcons["warning"] + `</div><div class="modal-title" id="confirm-title">Are you sure?</div><div class="modal-copy" id="confirm-copy">This action cannot be undone.</div><div class="modal-actions"><button class="btn" type="button" onclick="this.closest('dialog').close()">Cancel</button><button class="btn danger" id="confirm-submit" type="button">Continue</button></div></div></dialog><script>` + dashboardScript + `</script></body></html>`
}
func LandingPage(options LandingOptions) string {
	endpoint := Escape(options.Endpoint)
	accountAction := `<a class="btn ghost" href="/login">Sign in</a><a class="btn primary" href="/register">Create account</a>`
	heroSecondary := `<a class="btn" href="/register">Create account</a>`
	finalPrimary := `<a class="btn primary" href="/register">Create your account <span class="landing-btn-icon" aria-hidden="true">` + UIIcons["arrowRight"] + `</span></a>`
	if options.SignedIn {
		accountAction = `<a class="btn primary" href="/dashboard">Open dashboard</a>`
		heroSecondary = `<a class="btn" href="/dashboard">Open dashboard</a>`
		finalPrimary = `<a class="btn primary" href="/dashboard">Open your dashboard <span class="landing-btn-icon" aria-hidden="true">` + UIIcons["arrowRight"] + `</span></a>`
	}
	year := fmt.Sprint(time.Now().Year())
	return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="color-scheme" content="light"><meta name="theme-color" content="#f5f8ff">` + brandHead + `<meta name="description" content="Connect ChatGPT securely to project folders you explicitly authorize on your computer."><title>CodeLocal · Give ChatGPT secure access to your local code</title><style>` + styles + landingStyles + `</style></head><body class="landing-body"><div class="landing">
<nav class="landing-nav"><div class="landing-nav-inner"><a class="landing-brand" href="/"><img class="landing-logo" src="/assets/codelocal-icon.png" alt="CodeLocal"><span>CodeLocal</span></a><div class="landing-nav-center"><a href="#product">Product</a><a href="#workflow">How it works</a><a href="#setup">Setup</a><a href="#security">Security</a></div><div class="landing-links">` + accountAction + `</div></div></nav>
<main class="landing-main">
<section class="landing-hero"><div class="landing-hero-copy-wrap"><div class="landing-kicker"><span class="status-dot green"></span>Local-first MCP control plane</div><h1>Give ChatGPT hands on your machine.<span>You keep control.</span></h1><div class="landing-hero-copy">Connect ChatGPT to the project folders you explicitly authorize. CodeLocal keeps source code, secrets and terminal execution on your computer while the cloud coordinates identity, routing and permissions.</div><div class="landing-actions"><a class="btn primary" href="#setup">Set up CodeLocal <span class="landing-btn-icon" aria-hidden="true">` + UIIcons["arrowRight"] + `</span></a>` + heroSecondary + `</div><div class="landing-trust"><span class="trust-chip">` + UIIcons["shield"] + `Local-first</span><span class="trust-chip">` + UIIcons["check"] + `Approval gates</span><span class="trust-chip">` + UIIcons["folderCheck"] + `Explicit folders only</span></div></div>
<div class="hero-stage" aria-label="ChatGPT connects through CodeLocal to an authorized local machine"><div class="hero-glass"><div class="hero-glass-head"><div><div class="hero-glass-title">Secure local connection</div><div class="hero-glass-meta">ChatGPT ↔ CodeLocal ↔ your machine</div></div><span class="hero-live"><span class="status-dot green"></span>Ready</span></div><div class="hero-flow"><div class="hero-node"><img src="/assets/chatgpt-plugin-icon.png" alt="ChatGPT"></div><div class="hero-connector"><span class="hero-connector-icon">` + UIIcons["connect"] + `</span></div><div class="hero-node primary"><img src="/assets/codelocal-icon.png" alt="CodeLocal"></div><div class="hero-connector"><span class="hero-connector-icon">` + UIIcons["arrowRight"] + `</span></div><div class="hero-node">` + UIIcons["device"] + `</div></div><div class="hero-flow-labels"><span>ChatGPT</span><span>CodeLocal</span><span>Your machine</span></div><div class="hero-workspace"><div class="hero-workspace-main"><span class="hero-workspace-icon">` + UIIcons["folderCheck"] + `</span><div><div class="hero-workspace-title">Authorized workspace</div><div class="hero-workspace-meta">Loaded only when ChatGPT selects it</div></div></div><span class="badge green">Permission-aware</span></div></div></div></section>
<section class="landing-section" id="product"><div class="section-heading-row"><div><div class="section-kicker">Built for local development</div><h2 class="landing-section-title">Your code stays local. The workflow feels native.</h2></div><div class="section-copy">CodeLocal is a thin control plane between ChatGPT and your development machine. It exposes only what you authorize and keeps the heavy project runtime asleep until a workspace is selected.</div></div><div class="product-grid"><article class="product-card wide"><div class="product-icon">` + UIIcons["folderCheck"] + `</div><div class="product-title">Authorize projects, not your whole computer.</div><div class="product-copy">Run <strong>codelocal .</strong> inside a project once. Only that workspace becomes available to ChatGPT, and removing access never deletes your files.</div><div class="product-terminal">cd /path/to/project
codelocal .</div></article><article class="product-card narrow"><div class="product-icon">` + UIIcons["device"] + `</div><div class="product-title">One lightweight machine runtime.</div><div class="product-copy">Pair a computer once, keep CodeLocal running, and let multiple authorized workspaces sleep until a conversation needs them.</div><div class="product-badges"><span class="product-pill">macOS</span><span class="product-pill">Windows</span><span class="product-pill">Linux</span></div></article><article class="product-card half"><div class="product-icon">` + UIIcons["shield"] + `</div><div class="product-title">Sensitive actions stay gated.</div><div class="product-copy">Potentially destructive terminal and filesystem operations require approval before they execute on your machine.</div></article><article class="product-card half"><div class="product-icon">` + UIIcons["sparkles"] + `</div><div class="product-title">Work from the chat you already use.</div><div class="product-copy">Connect CodeLocal as a remote MCP server, select a workspace in ChatGPT, then read, edit and operate on that authorized project through the conversation.</div></article></div></section>
<section class="landing-section" id="workflow"><div class="section-kicker">How it works</div><h2 class="landing-section-title">Four layers. One simple mental model.</h2><div class="section-copy">ChatGPT reasons, CodeLocal Cloud handles identity and routing, your paired runtime performs local work, and workspace permissions define the boundary.</div><div class="how-grid"><article class="how-card"><div class="how-number">01</div><div class="how-title">Connect ChatGPT</div><div class="how-copy">Add the CodeLocal MCP endpoint and authenticate with OAuth.</div></article><article class="how-card"><div class="how-number">02</div><div class="how-title">Pair your machine</div><div class="how-copy">Run <strong>codelocal</strong> once and approve the device in your browser.</div></article><article class="how-card"><div class="how-number">03</div><div class="how-title">Authorize a project</div><div class="how-copy">Run <strong>codelocal .</strong> inside only the folders you want available.</div></article><article class="how-card"><div class="how-number">04</div><div class="how-title">Choose it in chat</div><div class="how-copy">The selected workspace activates on demand while everything else stays sleeping.</div></article></div></section>
<section class="setup-section" id="setup"><div class="section-kicker">Setup guide</div><h2 class="landing-section-title">From zero to connected in five steps.</h2><div class="section-copy">The detailed flow stays here when you need it; the product surface above remains focused on what CodeLocal actually does.</div><div class="setup-layout"><div class="setup-list">
<details class="setup-step" open><summary><span class="step-number">1</span><span><span class="step-title">Connect CodeLocal with ChatGPT</span><span class="step-summary">Create the remote MCP connection first.</span></span><span class="step-chevron">` + UIIcons["chevronRight"] + `</span></summary><div class="step-content"><ol class="step-details"><li>Open <strong>ChatGPT</strong>, go to Plugins and create a new plugin.</li><li>Use the CodeLocal plugin icon and set the server URL to <strong>` + endpoint + `</strong>.</li><li>Choose <strong>OAuth</strong>. Keep the automatically discovered OAuth endpoints.</li><li>Save the plugin, sign in to CodeLocal, then approve the connection.</li></ol></div></details>
<details class="setup-step"><summary><span class="step-number">2</span><span><span class="step-title">Install CodeLocal</span><span class="step-summary">Install the current beta runtime on your development machine.</span></span><span class="step-chevron">` + UIIcons["chevronRight"] + `</span></summary><div class="step-content"><div class="step-code">npm install -g codelocal@beta</div><div class="step-note"><strong>If npm reports EEXIST:</strong> run <code>npm uninstall -g codelocal</code>, then install again. Avoid <code>--force</code> unless you verified the conflicting file.</div></div></details>
<details class="setup-step"><summary><span class="step-number">3</span><span><span class="step-title">Pair this computer</span><span class="step-summary">Create a private device credential for this machine.</span></span><span class="step-chevron">` + UIIcons["chevronRight"] + `</span></summary><div class="step-content"><div class="step-code">codelocal</div><ol class="step-details"><li>Your browser opens the approval page automatically.</li><li>Sign in with the same CodeLocal account.</li><li>Verify the machine name, approve it, then return to the terminal.</li></ol></div></details>
<details class="setup-step"><summary><span class="step-number">4</span><span><span class="step-title">Authorize a project folder</span><span class="step-summary">Grant each workspace explicitly.</span></span><span class="step-chevron">` + UIIcons["chevronRight"] + `</span></summary><div class="step-content"><div class="step-code">cd /path/to/project
codelocal .</div><div class="step-note">Repeat <code>codelocal .</code> only inside projects you want ChatGPT to access.</div></div></details>
<details class="setup-step"><summary><span class="step-number">5</span><span><span class="step-title">Start working from ChatGPT</span><span class="step-summary">Keep the machine runtime on, then choose a workspace in chat.</span></span><span class="step-chevron">` + UIIcons["chevronRight"] + `</span></summary><div class="step-content"><ol class="step-details"><li>Enable <strong>CodeLocal</strong> in the conversation.</li><li>Ask it to list your authorized workspaces.</li><li>Select the project you need; sleeping workspaces activate only when selected.</li><li>Approve sensitive local actions when CodeLocal asks.</li></ol></div></details>
</div><aside class="plugin-panel"><div class="plugin-panel-head"><img class="plugin-panel-icon" src="/assets/chatgpt-plugin-icon.png" alt="CodeLocal ChatGPT plugin icon"><div><div class="plugin-panel-title">ChatGPT connection</div><div class="plugin-panel-sub">Production MCP endpoint</div></div></div><div class="plugin-endpoint"><div class="plugin-endpoint-label">Server URL</div><div class="plugin-endpoint-value">` + endpoint + `</div></div><div class="plugin-specs"><div class="plugin-spec"><span class="plugin-spec-key">Authentication</span><span class="plugin-spec-value">OAuth</span></div><div class="plugin-spec"><span class="plugin-spec-key">Transport</span><span class="plugin-spec-value">Remote MCP</span></div><div class="plugin-spec"><span class="plugin-spec-key">Plugin icon</span><span class="plugin-spec-value">256 × 256 PNG</span></div></div><button class="btn primary" type="button" data-copy-value="` + endpoint + `"><span class="landing-btn-icon" aria-hidden="true">` + UIIcons["copy"] + `</span>Copy Server URL</button><a class="btn" href="/assets/chatgpt-plugin-icon.png" download="codelocal-chatgpt-plugin-icon.png">Download plugin icon</a><div class="size-ok"><span class="size-ok-icon">` + UIIcons["check"] + `</span>Ready for ChatGPT plugin setup</div></aside></div></section>
<section class="security-section" id="security"><div class="security-hero"><div><div class="section-kicker">Private by design</div><h2 class="landing-section-title">Your machine is the security boundary.</h2><div class="section-copy">CodeLocal Cloud coordinates identity and routing; the source code, project secrets and execution context remain on the paired computer.</div></div><div class="security-mark" aria-hidden="true">` + UIIcons["shield"] + `</div></div><div class="security-points"><article class="security-card"><div class="security-icon">` + UIIcons["folderCheck"] + `</div><div class="security-title">Explicit workspace access</div><div class="security-copy">Only folders you authorize appear in ChatGPT. Revoking access leaves project files untouched.</div></article><article class="security-card"><div class="security-icon">` + UIIcons["check"] + `</div><div class="security-title">Approval for risky actions</div><div class="security-copy">Sensitive terminal and filesystem operations stay behind your local confirmation policy.</div></article><article class="security-card"><div class="security-icon">` + UIIcons["device"] + `</div><div class="security-title">Revocable device credentials</div><div class="security-copy">Review paired machines from the dashboard and revoke any device you no longer trust.</div></article></div></section>
<section class="final-cta"><div class="cta-card"><div class="cta-icon">` + UIIcons["sparkles"] + `</div><div class="cta-title">Give ChatGPT local capability without giving up local control.</div><div class="cta-copy">Pair one machine, authorize only the projects you choose, and keep the rest of your computer outside the boundary.</div><div class="cta-actions">` + finalPrimary + `<a class="btn" href="#setup">Read setup guide</a></div></div></section>
<footer class="landing-footer"><span class="landing-footer-brand"><img src="/assets/codelocal-icon.png" alt="">CodeLocal</span><span>© ` + year + ` · Local source code and secrets remain on your computer.</span></footer>
</main></div><script>` + landingScript + `</script></body></html>`
}

func MetricCard(label string, value any, sub string) string {
	return `<div class="card metric-card span4"><div class="metric-label">` + Escape(label) + `</div><div class="metric">` + Escape(fmt.Sprint(value)) + `</div><div class="metric-sub">` + Escape(sub) + `</div></div>`
}
